# eSpeak NG phoneme table kok
@kok::           -                       # ː  (not met)
@kok:@           @=m1                    # ə
@kok:@-          @=m1                    # ə
@kok:*           l=m2                    # ɾ
@kok:#X1         x=m3                    # ʰχ  (not met)
@kok:?           <q=m4                   # ʔ  (not met)
@kok:-           -                       # -  (not met)
@kok:t#          t=m5                    # tʰ  (not met)
@kok:#@          <h=m6 @=m1              # ʰə  (not met)
@kok:#a          <h=m6 a=m7              # ʰa  (not met)
@kok:#e          <h=m6 e=m8              # ʰe  (not met)
